#include <bits/stdc++.h>
using namespace std;

int fast_pow(int base, int power, int mod) {
    int result = 1;
    while (power > 0) {
        if (power & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod;
        power >>= 1;
    }
    return result;
}

const int MAXN = 300005;
unsigned long long dp_table[27][MAXN];
int factorial[MAXN], inv_factorial[MAXN];

int permute(int n, int m, int mod) {
    return (long long)factorial[n] * inv_factorial[n - m] % mod;
}

int main() {
    int n, K, MOD;
    scanf("%d %d %d", &n, &K, &MOD);
    if (n % 2 == 1) {
        printf("%d\n", fast_pow(K, n, MOD));
        return 0;
    }
    factorial[0] = 1;
    for (int i = 1; i <= n; ++i) {
        factorial[i] = (long long)factorial[i - 1] * i % MOD;
    }
    inv_factorial[n] = fast_pow(factorial[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
        inv_factorial[i] = (long long)inv_factorial[i + 1] * (i + 1) % MOD;
    }
    dp_table[0][0] = 1ULL;
    for (int k = 0; k < K; ++k) {
        for (int i = 1; i <= n; ++i) {
            if ((i & n) != i) continue;
            int block_mask = 1 << (31 - __builtin_clz(i));
            unsigned long long &res = dp_table[k + 1][i];
            res = 0ULL;
            for (int j = i - block_mask; j >= 0; j = (j - 1) & i) {
                int j_plus = j + block_mask;
                res += dp_table[k][i ^ j_plus] * inv_factorial[j_plus];
                if (++cnt == 17) {
                    res %= MOD;
                    cnt = 0;
                }
                if (j == 0) break;
            }
            res %= MOD;
        }
    }
    int total_ans = 0;
    for (int i = 0; i <= K; ++i) {
        total_ans = (total_ans + (long long)factorial[n] * dp_table[i][n] % MOD * permute(K, i, MOD)) % MOD;
    }
    printf("%d\n", (fast_pow(K, n, MOD) + MOD - total_ans) % MOD);
}
